<?php declare(strict_types=1); ?>
<!doctype html><html lang="<?= e(\App\Core\Translator::locale()) ?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= e(\App\Core\Translator::get('account.bookings.title')) ?></title><style>body{font-family:system-ui;background:#f6f8f6;color:#26332b;margin:0}.wrap{max-width:1000px;margin:35px auto;padding:0 18px}.item{background:white;border:1px solid #e7ece8;border-radius:13px;padding:18px;margin:12px 0;display:flex;justify-content:space-between;gap:15px}.muted{color:#6d796f}.tag{background:#eef5ef;padding:6px 10px;border-radius:20px;font-size:12px;height:max-content}@media(max-width:600px){.item{display:block}}.cancel{margin-top:12px;padding:12px;border:1px solid #e7ece8;border-radius:10px;background:#fbfcfb}.cancel textarea{display:block;width:100%;max-width:480px;min-height:64px;padding:9px;border:1px solid #dfe6e0;border-radius:8px;font:inherit}.cancel button{margin-top:8px;padding:10px 14px;border:0;border-radius:8px;background:var(--villa-primary,#176b50);color:#fff;font-weight:700}</style><?php require APP_ROOT . '/views/site/partials/account-theme.php'; ?></head><body><main class="wrap"><h1><?= e(\App\Core\Translator::get('account.bookings.title')) ?></h1><p class="muted"><?= e(\App\Core\Translator::get('account.bookings.intro')) ?></p><?php foreach($bookings as $booking): ?><article class="item"><div><strong><?= e($booking['title']) ?></strong><p class="muted"><?= e($booking['city']) ?> · <?= e(date('d.m.Y',strtotime($booking['check_in']))) ?> – <?= e(date('d.m.Y',strtotime($booking['check_out']))) ?> · <?= (int)$booking['guests'] ?> misafir</p><small><?= e($booking['booking_code']) ?></small><p><a href="<?= e(app_url('/account/messages/' . (int)$booking['id'])) ?>"><?= e(\App\Core\Translator::get('account.bookings.messages')) ?></a></p><?php if($booking['status']==='completed' && empty($booking['has_review'])): ?><p><a href="<?= e(app_url('/account/reviews/' . (int)$booking['id'])) ?>"><?= e(\App\Core\Translator::get('account.bookings.review')) ?></a></p><?php elseif(!empty($booking['has_review'])): ?><p class="muted"><?= e(\App\Core\Translator::get('account.bookings.review_sent')) ?></p><?php endif; ?><?php if(in_array($booking['status'],['pending','confirmed'],true)&&empty($booking['has_pending_cancellation'])&&strtotime($booking['check_in'].' 00:00:00')>=strtotime(date('Y-m-d').' 00:00:00')): ?><form class="cancel" method="post" action="<?= e(app_url('/account/bookings/cancel-request')) ?>"><?= csrf_field() ?><input type="hidden" name="booking_id" value="<?= (int)$booking['id'] ?>"><strong><?= e(\App\Core\Translator::get('account.bookings.cancel_title')) ?></strong><p class="muted">Politikaya göre tahmini iade: <?= e(number_format((float)$booking['estimated_refund'],2,',','.')) ?> <?= e($booking['currency']) ?> (<?= (int)$booking['estimated_refund_percent'] ?>%). Yönetici onayı gerekir.</p><textarea name="reason" maxlength="1000" placeholder="<?= e(\App\Core\Translator::get('account.bookings.cancel_reason')) ?>"></textarea><button type="submit"><?= e(\App\Core\Translator::get('account.bookings.cancel_submit')) ?></button></form><?php elseif(!empty($booking['has_pending_cancellation'])): ?><p class="muted"><?= e(\App\Core\Translator::get('account.bookings.cancel_pending')) ?></p><?php endif; ?></div><div><span class="tag"><?= e($booking['status']) ?></span><p><strong><?= e(number_format((float)$booking['total'],0,',','.')) ?> <?= e($booking['currency']) ?></strong></p></div></article><?php endforeach; ?><?php if(!$bookings): ?><p><?= e(\App\Core\Translator::get('account.bookings.empty')) ?></p><?php endif; ?><p><a href="<?= e(app_url('/account/notifications')) ?>"><?= e(\App\Core\Translator::get('account.bookings.notifications')) ?></a> · <a href="<?= e(app_url('/')) ?>"><?= e(\App\Core\Translator::get('account.bookings.discover')) ?></a></p><?php require APP_ROOT . '/views/site/partials/logout-button.php'; ?></main></body></html>